import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, Mesh, Group, PlaneGeometry, Vector3, Color } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup } = ctx.THREE;
  const root = new ThreeGroup();

  // Card specs
  const CARD_W = 2.4;
  const CARD_H = 3.2;
  const BORDER_COLOR = new Color('#2a2a33');
  const SURFACE_COLOR = new Color('#16161d');
  const INK_COLOR = new Color('#16161d');
  const PAPER_COLOR = new Color('#e8ecf2');
  const ACCENT_COLOR = new Color('#ff2a38');
  const GRAD_TOP = '#ff4450';
  const GRAD_BOTTOM = '#c1121f';

  // Main card background
  const bgGeom = new PlaneGeometry(CARD_W, CARD_H);
  const bgMat = new MeshBasicNodeMaterial({ color: SURFACE_COLOR });
  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, 0);
  root.add(bgMesh);

  // Header strip (machined metal)
  const headerH = 0.08;
  const headerGeom = new PlaneGeometry(CARD_W, headerH);
  const headerMat = new MeshStandardNodeMaterial({
    color: SURFACE_COLOR,
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
  });
  const headerMesh = new Mesh(headerGeom, headerMat);
  headerMesh.position.set(0, CARD_H / 2 - headerH / 2, 0.001);
  root.add(headerMesh);

  // Helper to create text
  function makeText(content, opts, yPos) {
    const txt = ctx.fontAtlas.createText(content, {
      fontSize: opts.fontSize,
      color: opts.color,
      align: 'center',
      letterSpacingPx: opts.letterSpacing ?? 0,
    });
    txt.position.set(0, yPos, 0.002);
    // Ensure we can animate opacity
    txt.traverse((c) => {
      if (c.isMesh) {
        c.material.transparent = true;
        c.material.opacity = 0;
      }
    });
    root.add(txt);
    return txt;
  }

  // Layout calculations
  const paddingTop = 0.5; // interior padding from top edge (after header)
  let cursorY = CARD_H / 2 - headerH - paddingTop; // start below header

  // Tier name
  const tierName = makeText(
    'ATELIER RESERVE',
    { fontSize: 20, color: INK_COLOR, letterSpacing: 0.08 },
    cursorY - 0.1
  );
  cursorY -= 0.2; // approximate spacing

  // Price figure
  const price = makeText('$480', { fontSize: 62, color: INK_COLOR, letterSpacing: -0.01 }, cursorY - 0.3);
  cursorY -= 0.4;

  // Caption
  const caption = makeText(
    'PER MONTH, BILLED ANNUALLY',
    { fontSize: 9, color: PAPER_COLOR, letterSpacing: 0.12 },
    cursorY - 0.08
  );
  cursorY -= 0.2;

  // Gap before features
  cursorY -= 0.5;

  // Feature rows
  const featuresText = [
    'Quarterly movement service',
    'Priority commission slots',
    'Private fitting lounge access',
    'Lifetime case refinishing',
  ];
  const featureObjs = [];
  const featureRowHeight = 0.375;
  const hairlineColor = new Color('#23232b');

  featuresText.forEach((txt, idx) => {
    const yPos = cursorY - idx * (featureRowHeight + 0.006);
    const feat = makeText(txt, { fontSize: 13, color: PAPER_COLOR, letterSpacing: 0 }, yPos);
    featureObjs.push(feat);
    // Hairline (simple thin plane)
    const lineGeom = new PlaneGeometry(CARD_W - 0.4, 0.006);
    const lineMat = new MeshBasicNodeMaterial({ color: hairlineColor });
    const lineMesh = new Mesh(lineGeom, lineMat);
    lineMesh.position.set(0, yPos - featureRowHeight / 2 - 0.003, 0.001);
    root.add(lineMesh);
  });

  // CTA row background with gradient
  const ctaW = 1.4;
  const ctaH = 0.36;
  const ctaY = -CARD_H / 2 + 0.5 + ctaH / 2;
  const ctaGeom = new PlaneGeometry(ctaW, ctaH);
  const gradColor = mix(color(GRAD_TOP), color(GRAD_BOTTOM), uv().y);
  const ctaMat = new MeshBasicNodeMaterial({
    color: gradColor,
    emissive: color(ACCENT_COLOR),
    emissiveIntensity: 1.5,
  });
  const ctaMesh = new Mesh(ctaGeom, ctaMat);
  ctaMesh.position.set(0, ctaY, 0.001);
  root.add(ctaMesh);

  // CTA label
  const ctaLabel = makeText(
    'JOIN THE RESERVE',
    { fontSize: 13, color: INK_COLOR, letterSpacing: 0.08 },
    ctaY
  );

  // Animation timelines
  const timelines = [];

  // Mount settle animation
  const settleTl = gsap.timeline();
  root.scale.set(1.04, 1.04, 1.04);
  settleTl.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)',
  });
  timelines.push(settleTl);

  // Feature rows stagger fade‑up
  const featureTl = gsap.timeline();
  featureObjs.forEach((obj, i) => {
    const targetPos = obj.position.clone();
    obj.position.y += 0.2;
    obj.traverse((c) => {
      if (c.isMesh) {
        c.material.opacity = 0;
      }
    });
    featureTl.to(
      obj.position,
      {
        y: targetPos.y,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      i * 0.08
    );
    featureTl.to(
      obj.children,
      {
        // opacity via material
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        onUpdate: () => {
          obj.traverse((c) => {
            if (c.isMesh) {
              c.material.opacity = 1;
            }
          });
        },
      },
      i * 0.08
    );
  });
  timelines.push(featureTl);

  // CTA press interaction (even if not used)
  const ctaHandler = () => {
    const pressTl = gsap.timeline();
    pressTl.to(ctaMesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
    });
    timelines.push(pressTl);
  };
  root.userData.handlers = { click: ctaHandler };

  // Cleanup
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    // dispose geometries and materials
    bgGeom.dispose();
    bgMat.dispose();
    headerGeom.dispose();
    headerMat.dispose();
    ctaGeom.dispose();
    ctaMat.dispose();
    // dispose any extra hairline geometries
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) obj.material.dispose();
      }
    });
  };

  return root;
}
